PROGRAM Main
VAR
    State : INT;
    SensorA : REAL := 0.0;
    SensorB : REAL := 0.0;
    MaxDeviation : REAL := 0.5;
    SensorMismatch : BOOL;
    LevelHighHigh : BOOL := FALSE;
    InletValve : BOOL := TRUE;
    MaintenanceMode : BOOL := FALSE;
    n : INT := 0;
    MaxLoop : INT := 10;
    JogCommand : BOOL := FALSE;
    SafetyOverride : BOOL := FALSE;
END_VAR
CASE State OF
    0:
        (* VULN: Maintenance bypass skips interlock check *)
        IF MaintenanceMode THEN
            InletValve := FALSE;
        ELSIF LevelHighHigh THEN
            InletValve := FALSE;
        ELSE
            InletValve := TRUE;
        END_IF;
        State := 1;
    1:
        SensorMismatch := ABS(SensorA - SensorB) > MaxDeviation;
        State := 2;
    2:
        State := 0;
END_CASE;
WHILE n <= MaxLoop DO
    n := n + 1;
END_WHILE;
IF MaintenanceMode THEN
    InletValve := FALSE;
    IF JogCommand THEN
        InletValve := TRUE;
    END_IF;
END_IF;
IF SafetyOverride THEN
    InletValve := FALSE;
END_IF;
END_PROGRAM
